package com.vandorlabs.client;

import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.tiles.TileEntityProgrammableLight;
import com.vandorlabs.items.ProgrammableSettings;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.lang.reflect.Field;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.BlockPos;

/** Actual Light scalar load/save/item projection and evaluation; loaded joining has a separate oracle. */
public final class ProgrammableLightLegacyChecks {
    private static final String[] FIELDS={"LightTexture","LightFaceTexture","LightOffFaceTexture","LightLevel","SignalBrightness","LightOffset","JoinedSignalLevel","LightOn","LightJoin","LightTrigger","LightGroupPowered","RedstoneChannel","RedstoneChannels","ChannelSignal","ChannelLevel","smallInput"};
    private static final BlockPos POS=new BlockPos(8,80,8);
    private static final class Output implements AutoCloseable {final java.io.PrintWriter out;final MessageDigest hash;final String kind;int rows;Output(String prefix,String kind)throws Exception{this.kind=kind;Path path=Paths.get(prefix+"-"+kind+"-forge.jsonl");Files.createDirectories(path.toAbsolutePath().getParent());out=new java.io.PrintWriter(Files.newBufferedWriter(path));hash=MessageDigest.getInstance("SHA-256");}void row(JsonObject row){String text=row.toString();out.println(text);hash.update(text.getBytes(StandardCharsets.UTF_8));rows++;}public void close(){out.close();StringBuilder golden=new StringBuilder();for(byte b:hash.digest())golden.append(String.format(Locale.ROOT,"%02x",b&255));int expected=kind.equals("settings")?771:66816;String frozen=kind.equals("settings")?"45447370b1c1cc8a9f83ac0a55bd479a1eb1d534711a0347185a8117fe29d318":"ca729e985ebf1079a3afb52303cb8bf9b56de8cba339408fb60426bc9cc1a49d";if(rows!=expected||!frozen.isEmpty()&&!golden.toString().equals(frozen))throw new AssertionError("Light source corpus changed "+kind+"/"+rows+"/"+golden);System.out.println("Actual programmable Light "+kind+" PASS rows="+rows+" golden="+golden);}}
    private static NBTTagCompound input(String field,int kind){NBTTagCompound root=new NBTTagCompound();switch(kind){case 0:break;case 1:root.setByte(field,(byte)1);break;case 2:root.setShort(field,(short)1);break;case 3:root.setInteger(field,-9);break;case 4:root.setInteger(field,0);break;case 5:root.setInteger(field,1);break;case 6:root.setInteger(field,15);break;case 7:root.setInteger(field,Integer.MAX_VALUE);break;case 8:root.setLong(field,2);break;case 9:root.setFloat(field,.5F);break;case 10:root.setDouble(field,-1);break;case 11:root.setString(field,"future:light-choice");break;case 12:root.setTag(field,new NBTTagCompound());break;case 13:root.setIntArray(field,new int[]{7,9});break;case 14:root.setFloat(field,-.5F);break;default:root.setDouble(field,-.5);}return root;}
    private static void settings(Output output,BlockProgrammableLight[] blocks)throws Exception{for(int family=0;family<blocks.length;family++)for(int index=-1;index<FIELDS.length;index++)for(int kind=0;kind<(index<0?1:16);kind++){NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);TileEntityProgrammableLight tile=new TileEntityProgrammableLight();NBTTagCompound input=index<0?new NBTTagCompound():input(FIELDS[index],kind);if(index>=0)tile.readFromNBT(input);world.states.put(POS,blocks[family].getDefaultState());tile.setWorld(world);tile.setPos(POS);world.tiles.put(POS,tile);JsonObject row=new JsonObject();row.addProperty("family",family);row.addProperty("fresh",index<0);row.addProperty("field",index<0?"":FIELDS[index]);row.addProperty("kind",kind);row.addProperty("input",input.toString());row.addProperty("save",tile.writeToNBT(new NBTTagCompound()).toString());row.addProperty("item",ProgrammableSettings.capture(world,POS).toString());row.addProperty("face",tile.getFaceTexture());row.addProperty("offFace",tile.getOffFaceTexture());row.addProperty("manual",tile.isManual());row.addProperty("small",tile.isSmallInput());row.addProperty("level",tile.getLightLevel());row.addProperty("on",tile.isOn());row.addProperty("emitted",blocks[family].getLightValue(blocks[family].getDefaultState(),world,POS));output.row(row);}}
    private static Field field(String name)throws Exception{Field value=TileEntityProgrammableLight.class.getDeclaredField(name);value.setAccessible(true);return value;}
    /** Isolates the Light evaluator from the separately owned inherited physical/channel sampler. */
    private static final class Probe extends TileEntityProgrammableLight {int directLevel;boolean powered;@Override public int getSignalLevel(){return directLevel;}@Override protected boolean isTriggerPowered(){return powered;}}
    private static void policy(Output output,BlockProgrammableLight[] blocks)throws Exception{Field trigger=field("trigger"),manual=field("on"),join=field("join"),numeric=field("signalBrightness"),configured=field("lightLevel"),offset=field("lightOffset"),joined=field("joinedLevel"),group=field("joinedTriggerPower");for(int family=0;family<blocks.length;family++){NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);Probe tile=new Probe();world.states.put(POS,blocks[family].getDefaultState());world.tiles.put(POS,tile);tile.setWorld(world);tile.setPos(POS);
        for(int mode=0;mode<3;mode++)for(boolean on:new boolean[]{false,true})for(boolean linked:new boolean[]{false,true})for(boolean brightness:new boolean[]{false,true})for(int direct=0;direct<(brightness?16:2);direct++)for(int joinedLevel=0;joinedLevel<(brightness?16:2);joinedLevel++)for(int value=0;value<(brightness?7:16);value++){int delta=brightness?new int[]{-15,-7,-1,0,1,7,15}[value]:0;trigger.setInt(tile,mode);manual.setBoolean(tile,on);join.setBoolean(tile,linked);numeric.setBoolean(tile,brightness);configured.setInt(tile,brightness?8:value);offset.setInt(tile,delta);joined.setInt(tile,joinedLevel);group.setBoolean(tile,joinedLevel>0);tile.directLevel=direct;tile.powered=direct>0;JsonObject row=new JsonObject();row.addProperty("family",family);row.addProperty("trigger",mode);row.addProperty("manualOn",on);row.addProperty("join",linked);row.addProperty("numeric",brightness);row.addProperty("configured",brightness?8:value);row.addProperty("direct",direct);row.addProperty("joined",joinedLevel);row.addProperty("offset",delta);row.addProperty("on",tile.isOn());row.addProperty("level",tile.getLightLevel());row.addProperty("emitted",blocks[family].getLightValue(blocks[family].getDefaultState(),world,POS));output.row(row);}
    }}
    public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityProgrammableLight.class,new ResourceLocation("vandorlabs","light_source_oracle"));BlockProgrammableLight[] blocks={new BlockProgrammableLight(),new BlockProgrammableLightFrame(),new BlockProgrammableLightSlab()};try(Output settings=new Output(args[0],"settings");Output policy=new Output(args[0],"policy")){settings(settings,blocks);policy(policy,blocks);}}
}
